/**
 * The one resolution of "which Cursor control plane, as whom" for hosted
 * transports. The verb-lane files sink (`files-backends/cursor-hosted.ts`)
 * and the domain-lane store API client (`store-api-client.ts`) both build on
 * these, so the pod credential and base URL resolve identically on every
 * wire — one place to change, no drift between lanes.
 */
/**
 * Same default as the hosted storage backend, inlined so these entrypoints
 * do not import CLI code.
 */
export const DEFAULT_CURSOR_EXTERNAL_API_URL = "https://api.cursor.com";
function trimTrailingSlash(raw) {
    const trimmed = raw.trim();
    return trimmed.endsWith("/") ? trimmed.slice(0, -1) : trimmed;
}
export function resolveCursorApiBaseUrl(options) {
    return trimTrailingSlash(options.baseUrl ?? process.env.CURSOR_API_BASE_URL ?? DEFAULT_CURSOR_EXTERNAL_API_URL);
}
/**
 * The pod credential is the whole authorization on every hosted wire: the
 * API resolves the caller's deployment from it, so there is no second,
 * narrower credential to manage. Fails loudly rather than defaulting —
 * calling the control plane as nobody is worse than not calling.
 */
export function resolveCursorApiKey(options) {
    const configured = options.resolveApiKey?.() ?? options.apiKey;
    const key = (configured ?? process.env.CURSOR_API_KEY)?.trim();
    if (key === undefined || key === "") {
        throw new Error("Cursor hosted transport requires CURSOR_API_KEY (deployment pod credential on Cursor hosting)");
    }
    return key;
}
export function resolveCursorApiFetch(options) {
    const impl = options.fetch ?? globalThis.fetch;
    if (typeof impl !== "function") {
        throw new Error("Cursor hosted transport requires fetch");
    }
    return impl;
}
